mapper.sql:
WHERE od.ENT_CODE = #{srchEntCode}


	AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
	AND ${srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))


	AND ${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 
	AND ${srchDateGbn} <= CONVERT(DATE, #{srchEndDate}, ${srchDateFormat})



	AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP'
	AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
	AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
	AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'






				AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) IN (#{item})


				AND dbo.Cryptography(od.OD_JOB_NO, ${srchNoType}_ENC, 1) = #{srchNo}






				AND ${srchNoType} IN (#{item})


				AND ${srchNoType} = #{srchNo}






AND chg.CHG_CODE_SYSTEM LIKE CONCAT(#{srchChgCodeSystem}, '%')


AND chg.CHG_CODE_SYSTEM IN ${srchChgCodeSystemIn}


AND cost.ACCOUNT_CODE = #{srchAccountCode}


AND cost.CUSTOMER_CODE = #{srchCustomerCode}




	AND cost.${srchArAp}_INVOICE_JOB_NO IS NOT NULL


	AND cost.${srchArAp}_INVOICE_JOB_NO IS NULL




AND cost.OD_JOB_NO IS NOT NULL


AND cost.OD_JOB_NO IS NULL


AND cost.CURRENCY_CODE = #{srchCurrencyCode}

WHERE od.ENT_CODE = #{searchInvoiceList.srchEntCode}


	AND ${searchInvoiceList.srchDateGbn} >= CONVERT(DATE, #{searchInvoiceList.srchStartDate}, ${searchInvoiceList.srchDateFormat}) 
	AND ${searchInvoiceList.srchDateGbn} < DATEADD(DAY, 1, CONVERT(DATE, #{searchInvoiceList.srchEndDate}, ${searchInvoiceList.srchDateFormat}))


	AND ${searchInvoiceList.srchDateGbn} >= CONVERT(DATE, #{searchInvoiceList.srchStartDate}, ${searchInvoiceList.srchDateFormat}) 
	AND ${searchInvoiceList.srchDateGbn} <= CONVERT(DATE, #{searchInvoiceList.srchEndDate}, ${searchInvoiceList.srchDateFormat})



	AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'EXP'
	AND od.BOUND = 'AIR' AND od.BOUND_TYPE = 'IMP'
	AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'EXP'
	AND od.BOUND = 'SEA' AND od.BOUND_TYPE = 'IMP'






				AND dbo.Cryptography(od.OD_JOB_NO, ${searchInvoiceList.srchNoType}_ENC, 1) IN (#{item})


				AND dbo.Cryptography(od.OD_JOB_NO, ${searchInvoiceList.srchNoType}_ENC, 1) = #{searchInvoiceList.srchNo}






				AND ${searchInvoiceList.srchNoType} IN (#{item})


				AND ${searchInvoiceList.srchNoType} = #{searchInvoiceList.srchNo}






AND chg.CHG_CODE_SYSTEM LIKE CONCAT(#{searchInvoiceList.srchChgCodeSystem}, '%')


AND chg.CHG_CODE_SYSTEM IN ${searchInvoiceList.srchChgCodeSystemIn}


AND cost.ACCOUNT_CODE = #{searchInvoiceList.srchAccountCode}


AND cost.CUSTOMER_CODE = #{searchInvoiceList.srchCustomerCode}




	AND cost.${searchInvoiceList.srchArAp}_INVOICE_JOB_NO IS NOT NULL


	AND cost.${searchInvoiceList.srchArAp}_INVOICE_JOB_NO IS NULL




AND cost.OD_JOB_NO IS NOT NULL


AND cost.OD_JOB_NO IS NULL


AND cost.CURRENCY_CODE = #{searchInvoiceList.srchCurrencyCode}

mapper.select:
/* InvoiceMapper.selectWorkFeeChargeList : 전자상거래 정산관리 작업료 리스트 조회 */
SELECT A.* ,SUM(A.AR_AMOUNT) OVER() AS TOTAL_AR_AMOUNT ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = A.ENT_CODE AND CODE = A.CD_TYPE_A AND GROUP_CODE = 'CD_TYPE') AS CD_TYPE ,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = A.ENT_CODE AND USER_ID = A.REGISTER_USER_ID_A) AS REGISTER_USER_NAME FROM( SELECT MAX(od.OD_JOB_NO) AS OD_JOB_NO ,MAX(od.BOUND) AS BOUND ,MAX(od.BOUND_TYPE) AS BOUND_TYPE ,MAX(inv.INVOICE_DATE) AS INVOICE_DATE ,MAX(inv.INVOICE_NO) AS INVOICE_NO ,MAX(od.CUST_CODE_LV1) AS CUST_CODE_LV1 ,MAX(od.CUST_CODE_LV2) AS CUST_CODE_LV2 ,MAX(od.AR_DATE) AS AR_DATE ,MAX(od.HBL_NO) AS HBL_NO ,MAX(od.PIECES) AS PIECES ,MAX(od.GWT) AS GWT ,MAX(CASE WHEN cost.CHARGE_CODE = 'WHF' THEN ISNULL(cost.AR_AMOUNT, 0) END) AS WHF_COST ,MAX(CASE WHEN cost.CHARGE_CODE = 'WHF' THEN ISNULL(cost.AR_AMOUNT_CUR, 0) END) AS WHF_COST_CUR ,MAX(CASE WHEN chg.CHG_CODE_SYSTEM = 'JOB_E' THEN ISNULL(cost.AR_AMOUNT, 0) END) AS OTC_COST ,ISNULL(SUM(cost.AR_AMOUNT), 0) AS AR_AMOUNT ,MAX(cost.CURRENCY_CODE) AS CURRENCY_CODE ,MAX(cost.CUSTOMER_CODE) AS CUSTOMER_CODE ,MAX(cost.CUSTOMER_NAME) AS CUSTOMER_NAME ,MAX(od.ENT_CODE) AS ENT_CODE ,MAX(od.CD_TYPE) AS CD_TYPE_A ,MAX(cost.REGISTER_USER_ID) AS REGISTER_USER_ID_A ,MAX(cost.AR_INVOICE_JOB_NO) AS AR_INVOICE_JOB_NO ,MAX(cost.AP_INVOICE_JOB_NO) AS AP_INVOICE_JOB_NO ,CASE WHEN cost.AP_INVOICE_JOB_NO = 'CLOSE' THEN 'Y' ELSE 'N' END AS CLOSE_YN ,MAX(od.REMARKS) AS REMARKS ,MAX(od.DELIVERY_NOTE) AS DELIVERY_NOTE ,MAX(od.TARIFF_REMARKS) AS TARIFF_REMARKS FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_COST cost ON cost.OD_JOB_NO = od.OD_JOB_NO INNER JOIN TB_SMS_CHARGE chg ON chg.ENT_CODE = od.ENT_CODE AND chg.CHARGE_CODE = cost.CHARGE_CODE LEFT JOIN TB_SAS_INVOICE inv ON inv.INVOICE_JOB_NO = cost.AR_INVOICE_JOB_NO
GROUP BY od.OD_JOB_NO, cost.AP_INVOICE_JOB_NO, cost.AR_INVOICE_JOB_NO, cost.CUSTOMER_CODE ) A

/* InvoiceMapper.selectCostBatchDelete : 전자상거래 COST 삭제대상 조회 */ SELECT od.OD_JOB_NO ,${invoiceAccountType} AS INVOICE_ACCOUNT_CODE ,MAX(od.MBL_NO) AS MBL_NO ,MAX(od.HBL_NO) AS HBL_NO ,MAX(cost.AR_INVOICE_JOB_NO) AS AR_INVOICE_JOB_NO ,MAX(cost.AP_INVOICE_JOB_NO) AS AP_INVOICE_JOB_NO FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_COST cost ON cost.OD_JOB_NO = od.OD_JOB_NO INNER JOIN TB_SMS_CHARGE chg ON chg.ENT_CODE = od.ENT_CODE AND chg.CHARGE_CODE = cost.CHARGE_CODE
WHERE od.ENT_CODE = #{entCode} AND(
(od.OD_JOB_NO = #{item.odJobNo} AND ${invoiceAccountType} = #{item.invoiceAccountCode})
) AND cost.AR_INVOICE_JOB_NO IS NULL AND cost.AP_INVOICE_JOB_NO IS NULL AND chg.CHG_CODE_SYSTEM LIKE CONCAT(#{invoiceType}, '%')
GROUP BY od.OD_JOB_NO, ${invoiceAccountType} ORDER BY od.OD_JOB_NO

mapper.delete:
/* InvoiceMapper.deleteCostBatch : 전자상거래 COST 삭제 */
	DELETE cost
	FROM TB_ECM_OD_COST cost
		 INNER JOIN TB_SMS_CHARGE chg
		 			ON chg.ENT_CODE = #{entCode}
		 			AND chg.CHARGE_CODE = cost.CHARGE_CODE
	WHERE cost.OD_JOB_NO = #{OD_JOB_NO}
	AND cost.AR_INVOICE_JOB_NO IS NULL
	AND cost.AP_INVOICE_JOB_NO IS NULL
	AND ${invoiceAccountType} = #{INVOICE_ACCOUNT_CODE}
	AND chg.CHG_CODE_SYSTEM LIKE CONCAT(#{invoiceType}, '%')

mapper.select:
/* InvoiceMapper.selectInvoiceNoCheck : 전자상거래 정산서생성 그룹정산번호체크 */
	SELECT COUNT(INVOICE_JOB_NO) AS CNT
	FROM TB_SAS_INVOICE
	WHERE ENT_CODE = #{entCode}
	AND ENT_BUSINESS_CODE = #{entBusinessCode}
	AND INVOICE_NO_GROUP = #{invoiceNoGroup}

mapper.insert:
/* InvoiceMapper.insertComOd : 전자상거래 정산서생성 TB_COM_OD insert */
	INSERT INTO TB_COM_OD(
		   OD_JOB_NO
		  ,OBL_JOB_NO
		  ,ENT_CODE
		  ,ENT_BUSINESS_CODE
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
		  ,SOLUTION
		  ,BOUND
		  ,BOUND_TYPE

		  ,OBAR_DATE

		  ,MBL_NO
		  ,HBL_NO
	)VALUES(
		   #{comOdJobNo}
		  ,#{oblJobNo}
		  ,#{entCode}
		  ,#{entBusinessCode}
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,'ECM'
		  ,#{bound}
		  ,#{boundType}

		  ,#{obarDate}

		  ,LTRIM(RTRIM(REPLACE(#{mblNo},char(9),'')))
		  ,LTRIM(RTRIM(REPLACE(#{hblNo},char(9),'')))
	)

/* InvoiceMapper.insertComOdForStorage : 보세구역관리 창고료정산 > 세금계산서 TB_COM_OD insert */
	INSERT INTO TB_COM_OD(
		   OD_JOB_NO
		  ,OBL_JOB_NO
		  ,ENT_CODE
		  ,ENT_BUSINESS_CODE
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
		  ,SOLUTION
		  ,BOUND
		  ,BOUND_TYPE

		  ,OBAR_DATE

		  ,MBL_NO
		  ,HBL_NO

		  ,CUSTOMER_CODE


		  ,CUSTOMER_NAME


		  ,CUSTOMER_ATTN


		  ,CUSTOMER_TEL

	)VALUES(
		   #{comOdJobNo}
		  ,#{oblJobNo}
		  ,#{entCode}
		  ,#{entBusinessCode}
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{solution}
		  ,#{bound}
		  ,#{boundType}

		  ,#{obarDate}

		  ,LTRIM(RTRIM(#{mblNo}))
		  ,LTRIM(RTRIM(#{hblNo}))

		  ,#{customerCode}


		  ,#{customerName}


		  ,#{attn}


		  ,#{tel}

	)

/* InvoiceMapper.insertComOdChg : 전자상거래 정산서생성 TB_COM_OD_CHG_INVOICE insert */
	INSERT INTO TB_COM_OD_CHG_INVOICE(
		   OD_JOB_NO
		  ,CHARGE_SEQ_NO
		  ,SOLUTION
		  ,INVOICE_BUS_CODE
		  ,LOCAL_OVERSEA
		  ,AR_AP
