		  ,CHARGE_NAME
		  ,VAT_YNX
		  ,VAT_PERCENT
		  ,CURRENCY_CODE_CUR
		  ,CURRENCY_CODE_LOC
		  ,EXCHANGE_RATE
		  ,AMOUNT_CUR
		  ,AMOUNT_VAT_CUR
		  ,AMOUNT_TOTAL_CUR
		  ,AMOUNT_LOC
		  ,AMOUNT_VAT_LOC
		  ,AMOUNT_TOTAL_LOC
		  ,EXRATE_USD
