		  ,#{item.chargeCode}
		  ,#{item.chargeName}
		  ,#{item.vatYnx}
		  ,#{item.vatPercent}
		  ,#{item.currencyCodeCur}
		  ,'KRW'
		  ,#{item.exchangeRate}
		  ,#{item.amountCur}
		  ,#{item.amountVatCur}
		  ,#{item.amountTotalCur}
		  ,#{item.amountLoc}
		  ,#{item.amountVatLoc}
		  ,#{item.amountTotalLoc}
		  ,#{item.exrateUsd}
		  ,#{item.amountUsd}
		  ,#{item.amountVatUsd}
		  ,#{item.amountTotalUsd}
		  ,#{item.accountCode}
		  ,'Y'
		  ,#{item.invoiceJobNo}
		  ,#{item.invoiceNo}
		  ,CONVERT(DATE, #{item.invoiceDate}, ${item.dateFormat})
		  ,'Y'

		  ,#{item.RATE_MULTIPLY}
		  ,#{item.RATE_QTY_WT}
		  ,#{item.RATE_CUR}
		  ,#{item.RATE_LOC}
		  ,#{item.accountName}

	)

/* InvoiceMapper.insertComOdChgForStorage : 보세구역관리 창고료정산 > 세금계산서 TB_COM_OD_CHG_INVOICE insert */
