mapper.update:
/* InvoiceMapper.updateEcmOdChg : 전자상거래 정산서생성 TB_ECM_OD_CHG_INVOICE update */
	UPDATE TB_ECM_OD_CHG_INVOICE
	   SET INVOICE_JOB_NO = #{invoiceJobNo}
	     , INVOICE_NO = #{invoiceNo}
	     , INVOICE_DATE = #{invoiceDate}
	     , INVOICE_CONFIRM_YN = 'Y'
	WHERE OD_JOB_NO = #{odJobNoList[0]}
	AND INVOICE_JOB_NO IS NULL
	AND INVOICE_BUS_CODE = #{entBusinessCode}
    AND INVOICE_CONFIRM_YN = 'N'

mapper.insert:
/* InvoiceMapper.insertInvoice : 전자상거래 정산서생성 TB_SAS_INVOICE insert */
	INSERT INTO TB_SAS_INVOICE(
		   INVOICE_JOB_NO
		  ,ENT_CODE
		  ,ENT_BUSINESS_CODE
		  ,INVOICE_NO
		  ,INVOICE_NO_CUSTOMER
		  ,SOLUTION
		  ,BOUND
		  ,BOUND_TYPE
		  ,LOCAL_OVERSEA
		  ,AR_AP
		  ,DOC_ISSUE_TYPE
		  ,HBL_INV_YN
		  ,OD_JOB_NO
		  ,INVOICE_DATE
		  ,ACCOUNT_CODE
		  ,ACCOUNT_NAME
		  ,ACCOUNT_ATTN_ID
		  ,ACCOUNT_ATTN
		  ,ACCOUNT_TEL
		  ,ACCOUNT_FAX
		  ,PAYMENT_ACCOUNT_CODE
		  ,CURRENCY_CODE_CUR
		  ,EXRATE_TYPE
		  ,EXRATE_DATE
		  ,EXCHANGE_RATE
		  ,AMOUNT_CUR
		  ,AMOUNT_VAT_CUR
		  ,AMOUNT_TOTAL_CUR
		  ,DR_AMOUNT_TOTAL_CUR
		  ,CR_AMOUNT_TOTAL_CUR
		  ,CURRENCY_CODE_LOC
		  ,AMOUNT_LOC
		  ,AMOUNT_VAT_LOC
		  ,AMOUNT_TOTAL_LOC
		  ,DR_AMOUNT_TOTAL_LOC
		  ,CR_AMOUNT_TOTAL_LOC
		  ,CURRENCY_TOTAL
		  ,EXRATE_USD
		  ,AMOUNT_TOTAL_USD
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
		  ,ACCOUNT_ATTN_ID_EBILL_YN
		  ,REMARKS
		  ,PREPAID_YN
	)VALUES(
		   #{invoiceJobNo}
		  ,#{entCode}
		  ,#{entBusinessCode}
		  ,#{invoiceNo}
		  ,#{invoiceNoCustomer}
		  ,'ECM'
		  ,#{bound}
		  ,#{boundType}
		  ,#{localOversea}
		  ,#{arAp}
		  ,'OP-GENERAL'
		  ,'Y'
		  ,#{comOdJobNo}
		  ,CONVERT(DATE, #{invoiceDate}, ${dateFormat})
		  ,#{accountCode}
		  ,#{accountName}
		  ,#{accountAttnId}
		  ,#{accountAttn}
		  ,#{accountTel}
		  ,#{accountFax}
		  ,#{accountCode}
		  ,#{currencyCodeCur}
		  ,#{exrateType}
		  ,#{exrateDate}
		  ,#{exchangeRate}
		  ,#{amountCur}
		  ,#{amountVatCur}
		  ,#{amountTotalCur}
		  ,#{drAmountTotalCur}
		  ,#{crAmountTotalCur}
		  ,'KRW'
		  ,#{amountLoc}
		  ,#{amountVatLoc}
		  ,#{amountTotalLoc}
		  ,#{drAmountTotalLoc}
		  ,#{crAmountTotalLoc}
		  ,#{currencyTotal}
		  ,#{exrateUsd}
		  ,#{amountTotalUsd}
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{accountAttnEbillYn}
		  ,#{remarks}
		  ,'N'
	)

/* InvoiceMapper.insertInvoiceItem : 전자상거래 정산서생성 TB_SAS_INVOICE_ITEM insert */ INSERT INTO TB_SAS_INVOICE_ITEM( INVOICE_JOB_NO ,CHARGE_SEQ_NO ,OD_JOB_NO ,AR_AP ,CHARGE_CODE ,CHARGE_NAME ,VAT_YNX ,VAT_PERCENT ,CURRENCY_CODE_CUR ,EXCHANGE_RATE ,AMOUNT_CUR ,AMOUNT_VAT_CUR ,AMOUNT_TOTAL_CUR ,CURRENCY_CODE_LOC ,AMOUNT_LOC ,AMOUNT_VAT_LOC ,AMOUNT_TOTAL_LOC ,EXRATE_USD ,AMOUNT_USD ,AMOUNT_VAT_USD ,AMOUNT_TOTAL_USD ,UPDATE_USER_ID ,UPDATE_DATE_TIME
,RATE_MULTIPLY ,RATE_QTY_WT ,RATE_CUR ,RATE_LOC
) SELECT INVOICE_JOB_NO ,CHARGE_SEQ_NO ,OD_JOB_NO ,AR_AP ,CHARGE_CODE ,CHARGE_NAME ,VAT_YNX ,VAT_PERCENT ,CURRENCY_CODE_CUR ,EXCHANGE_RATE ,AMOUNT_CUR ,AMOUNT_VAT_CUR ,AMOUNT_TOTAL_CUR ,CURRENCY_CODE_LOC ,AMOUNT_LOC ,AMOUNT_VAT_LOC ,AMOUNT_TOTAL_LOC ,EXRATE_USD ,AMOUNT_USD ,AMOUNT_VAT_USD ,AMOUNT_TOTAL_USD ,#{userId} ,DATEADD(HOUR, ${gmtTime}, GETDATE())
,RATE_MULTIPLY ,RATE_QTY_WT ,RATE_CUR ,RATE_LOC
FROM TB_COM_OD_CHG_INVOICE WHERE OD_JOB_NO = #{comOdJobNo}
ANd CURRENCY_CODE_CUR = #{currencyCodeCur}

mapper.update:
/* InvoiceMapper.updateOdCost : 전자상거래 정산서생성 TB_ECM_OD_COST update */ UPDATE cost SET cost.${srchArAp}_INVOICE_JOB_NO = #{invoiceJobNo} ,cost.${srchArAp}_INVOICE_DATE = CONVERT(DATE, #{invoiceDate}, ${srchDateFormat})
,cost.AR_AMOUNT = CASE WHEN ISNULL(cost.AR_AMOUNT, 0) = 0 AND cost.AR_INVOICE_JOB_NO IS NULL THEN cost.AP_AMOUNT ELSE cost.AR_AMOUNT END
FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_COST cost ON cost.OD_JOB_NO = od.OD_JOB_NO INNER JOIN TB_SMS_CHARGE chg ON chg.ENT_CODE = od.ENT_CODE AND chg.CHARGE_CODE = cost.CHARGE_CODE

mapper.insert:
/* InvoiceMapper.insertOblForStorage : 보세구역관리 창고료정산 > 세금계산서 TB_COM_OBL insert */ INSERT INTO TB_COM_OBL ( OBL_JOB_NO ,ENT_CODE ,SOLUTION ,BOUND ,BL_TYPE_MH ,MBL_NO ,HBL_NO ,SHIPPER_NAME ,SHIPPER_ADDRESS ,SHIPPER_ADDRESS_A ,SHIPPER_ADDRESS_B ,SHIPPER_ADDRESS_C ,SHIPPER_ADDRESS_D ,CONSIGNEE_NAME ,CONSIGNEE_ADDRESS ,CONSIGNEE_ADDRESS_A ,CONSIGNEE_ADDRESS_B ,CONSIGNEE_ADDRESS_C ,CONSIGNEE_ADDRESS_D ,VESSEL_FLIGHT ,VESSEL_VOYAGE
,AR_DATE
,AR_TIME
,REGISTER_USER_ID ,REGISTER_DATE_TIME ,UPDATE_USER_ID ,UPDATE_DATE_TIME )VALUES( #{oblJobNo} ,#{entCode} ,#{solution} ,#{bound} ,#{blTypeMh} ,#{mblNo} , #{hblNo}#{blNo}
,'' ,'' ,'' ,'' ,'' ,'' ,'' ,'' ,'' ,'' ,'' ,''
,#{vesselFlight} ,#{voyage}
,#{arDate}
,#{arTime}
,#{userId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) ,#{updateUserId} ,DATEADD(HOUR, ${gmtTime}, GETDATE()) );

mapper.update:
/* InvoiceMapper.updateWorkFeeClose : 전자상거래 작업료마감 */ UPDATE cost SET cost.AP_INVOICE_JOB_NO = #{invoiceJobNo} ,cost.AP_INVOICE_DATE = CASE WHEN #{invoiceJobNo} IS NOT NULL THEN GETDATE() ELSE NULL END FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_COST cost ON cost.OD_JOB_NO = od.OD_JOB_NO INNER JOIN TB_SMS_CHARGE chg ON chg.ENT_CODE = od.ENT_CODE AND chg.CHARGE_CODE = cost.CHARGE_CODE
AND cost.AP_INVOICE_JOB_NO IS NOT NULL
AND cost.AP_INVOICE_JOB_NO IS NULL

/* InvoiceMapper.updateOdChgInvoiceNoNull : Invoice No를 null로 업데이트 */
	UPDATE TB_COM_OD_CHG_INVOICE SET
		   INVOICE_NO = null
	WHERE INVOICE_NO = #{invoiceNo}
	AND INVOICE_JOB_NO IS NULL
	AND INVOICE_BUS_CODE = #{entBusinessCode}
	AND INVOICE_CONFIRM_YN = 'N'

mapper.select:
/* InvoiceMapper.selectWorkFeeRate : 작업료 요율 조회 */ SELECT od.OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,od.CUST_CODE_LV${customerLv} ,tar.WEIGHT_BASE ,tar.RATE_BASE ,tar.WEIGHT_INC ,tar.RATE_INC ,tar.CURRENCY_CODE ,tar.RATE_TYPE_APPLY ,tar.CHARGE_CODE ,(SELECT CHG_NM_KOR FROM TB_SMS_CHARGE WHERE ENT_CODE = tar.ENT_CODE AND CHARGE_CODE = tar.CHARGE_CODE) AS CHARGE_NAME ,CASE tar.RATE_TYPE_APPLY WHEN 'LBS' THEN od.GWT_LBS WHEN 'CBM' THEN od.CBM ELSE od.GWT END AS WORK_WEIGHT ,(SELECT 1 FROM TB_ECM_OD_COST WHERE OD_JOB_NO = od.OD_JOB_NO AND CHARGE_CODE = tar.CHARGE_CODE AND (AR_INVOICE_JOB_NO IS NOT NULL OR AP_INVOICE_JOB_NO IS NOT NULL)) AS INVOICE_JOB_NO ,(SELECT CUSTOMER_NAME FROM TB_SMS_CUSTOMER WHERE ENT_CODE = od.ENT_CODE AND CUSTOMER_CODE = od.CUST_CODE_LV${customerLv}) AS CUST_NAME_LV${customerLv} FROM TB_ECM_OD od INNER JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO INNER JOIN TB_SMS_TARIFF tar ON tar.ENT_CODE = od.ENT_CODE AND tar.ENT_BUSINESS_CODE = #{entBusinessCode} AND tar.CHARGE_CODE IS NOT NULL AND tar.CHARGE_CODE != '' AND tar.BOUND IN(od.BOUND, 'COM') AND tar.BOUND_TYPE = 'IMP' AND tar.RATE_TABLE_TYPE = 'JOB' AND tar.ACCOUNT_CODE = od.CUST_CODE_LV${customerLv} AND ISNULL(tar.SHIPMENT_GUBN, '') IN('', od.CD_TYPE) AND ISNULL(tar.ITEM_GUBN, '') IN('', od.ECM_TYPE)
AND tar.START_DATE <= od.AR_DATE AND tar.END_DATE >= od.AR_DATE AND ( tar.RATE_TYPE_APPLY = 'BL' OR (tar.WEIGHT_BASE < CASE tar.RATE_TYPE_APPLY WHEN 'LBS' THEN od.GWT_LBS WHEN 'CBM' THEN od.CBM ELSE od.GWT END AND tar.END_WEIGHT >= CASE tar.RATE_TYPE_APPLY WHEN 'LBS' THEN od.GWT_LBS WHEN 'CBM' THEN od.CBM ELSE od.GWT END) )
WHERE od.ENT_CODE = #{entCode} AND od.BOUND_TYPE = 'IMP'
AND od.CUST_CODE_LV${customerLv} = #{customerCode}
AND ISNULL(od.CUST_CODE_LV${customerLowLv}, '') = ''
AND od.BL_TYPE_MH = 'H' AND od.AR_DATE >= CONVERT(DATE, #{startDate}, ${dateFormat}) AND od.AR_DATE <= CONVERT(DATE, #{endDate}, ${dateFormat})

mapper.insert:
/* InvoiceMapper.insertWorkFee : 작업료 insert */
	DELETE FROM TB_ECM_OD_COST
	WHERE OD_JOB_NO = #{OD_JOB_NO}
	AND CHARGE_CODE = #{CHARGE_CODE};
	INSERT INTO TB_ECM_OD_COST(
		   OD_JOB_NO
		  ,SEQ_NO_ID
		  ,CHARGE_CODE
		  ,CHARGE_NAME
		  ,AR_AMOUNT
		  ,AR_AMOUNT_CUR
		  ,CURRENCY_CODE
		  ,PAYMENT_GUBN
		  ,CUSTOMER_CODE
		  ,CUSTOMER_NAME
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
	)VALUES(
		   #{OD_JOB_NO}
		  ,(SELECT ISNULL(MAX(SEQ_NO_ID), 0) + 1 FROM TB_ECM_OD_COST dim WHERE OD_JOB_NO = #{OD_JOB_NO})
		  ,#{CHARGE_CODE}
		  ,#{CHARGE_NAME}
		  ,#{amount}
		  ,#{amountCur}
		  ,#{CURRENCY_CODE}
		  ,'07'
		  ,#{CUST_CODE_LV${customerLv}}
		  ,#{CUST_NAME_LV${customerLv}}
		  ,#{userId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	);
